basic.fetcher:
(async function (args, reqOptions) {
  const baseUrl = await BeaconBar.executeFunction("reqOptions")();

  const finalUrl = `${baseUrl}GPAdding/Api/widgets/ExternalSlipApi/GetPayType`;


  return {
    url: finalUrl,
    method: "POST",
    headers: {
      "x-requested-with": "XMLHttpRequest",
      "Content-Type": "application/json"
    },
    credentials: "include",
    body: JSON.stringify({})
  };
})

basic.transformer:
(function (data, args, reqOptions) {
  return data.map(item => ({
    PayType: item.PayType,
    PayTypeName: item.PayTypeName
  }));
})

basic.sourceConstructor:
(function(data, args, reqOptions) {
  return data.map(item => ({
    url: "",
    title: item.PayTypeName,
    subTitle: `Pay Type: ${item.PayType}`,
    icon: ""
  }));
})

